const state={documentBusy:false,importStatus:{},step:0,jd:'',resume:'',roles:['lin'],round:'1',interviewType:'general',focusTopics:['self_intro','common'],durationMinutes:30,startsAt:localDate(Date.now()+15*60000),timezone:'Asia/Taipei',consent:false,status:null,stream:null,audioContext:null,meterFrame:null,session:null,sessionStarted:null,timer:null,transcript:'',report:null,error:'',busy:false,cameraState:'尚未啟用',micState:'尚未啟用',trialNotice:null,analysis:null,analysisBusy:false,practiceMode:false,practiceHistory:[],practiceDraft:'',practiceBusy:false,practiceAbort:null,practiceError:'',practiceReport:null,autoEndAttempted:false,lastSessionId:null,liveHistory:[],transcriptState:'idle',transcriptNotice:'',transcriptError:'',transcriptBusy:false,reportBusy:false,reportError:'',reportAbort:null,sessionDocuments:null,lastSessionRound:null,continuation:null,continuationBusy:false,continuationError:''};
function localDate(ms){const d=new Date(ms+8*3600000);return d.toISOString().slice(0,16)}
