async function api(path,options={}){let response;try{response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}})}catch(error){if(error.name==='AbortError')throw error;throw new Error('目前無法連上面試服務，請檢查網路後再試。')}const body=await response.json().catch(error=>{if(error.name==='AbortError')throw error;return {}});if(!response.ok)throw new Error(body.message||body.error?.message||(typeof body.error==='string'?body.error:null)||`服務暫時無法完成請求（${response.status}）`);return body}
async function loadStatus(){try{state.status=await api('/api/status');if(state.status.lastSessionId&&!state.lastSessionId)state.lastSessionId=state.status.lastSessionId;const ready=state.status.configured;$('#api-badge').textContent=state.status.configError?'服務設定需修正':ready?(state.status.liveVerified?'影音可用':'影音已設定 · 待實測'):state.status.llmConfigured?'文字已設定 · 影音待設定':'服務待設定';$('#api-badge').classList.toggle('warning',!ready||!state.status.liveVerified);syncHomeDuration()}catch{state.status={configured:false};$('#api-badge').textContent='面試服務目前離線';$('#api-badge').classList.add('warning')}render()}
function callLimitSeconds(){const seconds=state.status?.maxCallSeconds;return Number.isInteger(seconds)&&seconds>=30&&seconds<=2700?seconds:null}
function plannedCallSeconds(){return Math.min(state.durationMinutes*60,callLimitSeconds()??2700)}
function callDurationLabel(seconds=plannedCallSeconds()){return seconds%60===0?`${seconds/60} 分鐘`:`${seconds} 秒`}
function capNotice(){const limit=callLimitSeconds();return limit&&limit<900?`<div class="warning-box"><h3>${callDurationLabel(limit)}測試</h3>本場真人通話最多 ${callDurationLabel(limit)}，到時會嘗試結束連線；遠端亦設有相同時長上限。不會自動重新開始。</div>`:''}
function syncHomeDuration(){const limit=callLimitSeconds(),test=Boolean(limit&&limit<900);const range=$('#home-duration');if(!range)return;range.disabled=test;range.hidden=test;range.setAttribute('aria-label',test?`測試通話固定 ${callDurationLabel(limit)}`:'面試時長');$('#home-duration-output').textContent=test?limit/60:range.value;$('#home-duration-label').textContent=test?'測試通話時長':'面試時長';$('#home-duration-ends').innerHTML=test?`最多 ${callDurationLabel(limit)}`:'<span>15 min</span><span>45 min</span>';$('#use-duration').textContent=test?'使用測試時長 ↗':'使用此時長 ↗';$('#home-duration-fact').innerHTML=test?`${limit/60}<small>min</small>`:'15—45<small>min</small>';$('#home-duration-caption').textContent=test?'目前測試上限':'依自己的節奏安排'}
function heading(eyebrow,title,description,index){return `<div class="page-heading"><div><h2>${title}</h2><p>${description}</p></div><div class="page-index">0${index}</div></div>`}
