function render(){document.body.classList.toggle('meeting-view',state.step===4);if(state.session&&state.step===4&&$('#stage iframe')){const button=$('#end-session');if(button){button.disabled=state.busy;button.textContent=state.busy?'正在結束…':'結束面試'}let error=$('#live-error');if(!error){error=document.createElement('div');error.id='live-error';error.className='inline-error';error.setAttribute('role','alert');$('#content').append(error)}error.textContent=state.error;return}clearInterval(state.timer);$('#breadcrumb').textContent=`${state.step<4?'面試準備':'我的面試'} / ${stepNames[state.step]}`;$('#steps').innerHTML=stepNames.map((name,i)=>`<button data-step="${i}" ${state.step===i?'aria-current="step"':''} class="${state.step===i?'active':i<state.step?'completed':''}" ${state.session&&i!==4?'disabled':''}><span class="step-number">${i<state.step?'✓':String(i+1).padStart(2,'0')}</span>${name}</button>`).join('');$('#steps').querySelectorAll('button').forEach(b=>b.onclick=()=>go(Number(b.dataset.step)));const renderers=[renderDocuments,renderRoles,renderSchedule,renderDevices,renderInterview,renderReport];renderers[state.step]();renderRecovery();$('#back')?.addEventListener('click',()=>go(state.step-1));if(state.error){const error=document.createElement('div');error.className='inline-error';error.setAttribute('role','alert');error.textContent=state.error;$('#content').append(error)}}
function go(step){if(state.documentBusy){announce('正在讀取文件，請稍候。');return}if(state.busy)return;if(state.continuationBusy){announce('正在準備下一面，請稍候。');return}if(state.reportBusy){announce('請先中止回饋請求，再切換頁面。');return}if(state.practiceBusy){announce('請先中止目前的文字請求，再切換頁面。');return}if(state.session&&step!==4){announce('請先結束目前面試，再離開面試室。');return}if(step>0&&step!==5&&(state.jd.trim().length<20||state.resume.trim().length<20)){announce('請讓職缺內容與履歷各至少 20 字，面試才有足夠依據。');return}if(step>0&&step!==5&&new TextEncoder().encode(state.jd+state.resume).length>110000){announce('JD 與履歷合計超過 110 KB，請精簡後再繼續。');return}if(step>1&&!state.roles.length){announce('請先選擇至少一位面試官。');return}if(step===5&&!state.transcript&&!state.report&&!state.lastSessionId&&!state.practiceReport){announce('完成面試後，再到這裡查看回饋與紀錄。');return}if(state.step===3&&step!==3)stopDevices();state.error='';state.step=Math.max(0,Math.min(5,step));render();const heading=$('#content h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}window.scrollTo({top:0,behavior:'smooth'})}
function renderDocuments(){$('#content').innerHTML=heading('START WITH YOUR STORY','上傳職缺與履歷','放入 JD 和履歷，確認面試方向。',1)+continuationBanner()+`<div class="document-tools"><button class="secondary" id="load-trial">載入範例</button><span class="subtext">真實 JD 摘要＋虛構履歷；將取代目前欄位。</span></div>${state.trialNotice?trialNoticeHtml():''}<div class="two-columns">${documentPanel('jd','職缺說明（JD）','JOB DESCRIPTION','貼上職缺的工作內容、必要條件與加分條件。\n\n例如：\nAI Application Engineer\n・設計 RAG 與 Agent 工作流程\n・整合 API，將 AI 導入實際營運\n・具備 Python 與跨部門溝通能力')}${documentPanel('resume','我的履歷','YOUR RESUME','貼上你的履歷、專案及工作經歷。\n\n我們會根據你真正寫下的內容追問；沒有提及的經歷，會留待你親自說明。')}</div><div class="note"><span>↳</span><span>支援貼上文字或匯入 <strong>PDF / TXT / MD</strong>；PDF 最多 10 MB、20 頁，需可選取文字。每份 20–30,000 字，合計最多 110 KB。掃描圖片暫不支援。PDF 在瀏覽器內解析；首次使用需連網載入解析工具。</span></div><div class="analysis-actions"><button class="secondary" id="analyze-documents" ${state.analysisBusy?'disabled':''}>${state.analysisBusy?'正在檢查…':'檢查職缺與履歷'}</button><span class="subtext">先核對原文與關鍵字；這不是模型能力判定。</span></div>${state.analysis?analysisHtml():''}`+bottom('資料不會儲存在瀏覽器中。','選擇面試官',false);['jd','resume'].forEach(key=>{$(`#${key}`).addEventListener('input',e=>{if(state[key]!==e.target.value)clearContinuation('已更改面試資料，下一場改為獨立練習。');state[key]=e.target.value;state.analysis=null;state.trialNotice=null;$('.evidence-panel')?.remove();$('#trial-notice')?.remove();resetPractice();$(`#${key}-count`).textContent=`${state[key].length.toLocaleString()} 字`});$(`#${key}-file`).onchange=e=>readFile(e,key)});$('#load-trial').onclick=loadTrial;$('#analyze-documents').onclick=analyzeDocuments;$('#next').onclick=()=>go(1);bindContinuation()}
function documentPanel(key,title,label,placeholder){return `<section class="panel"><div class="panel-heading"><h3>${title}</h3><span class="small-tag">${label}</span></div><textarea id="${key}" maxlength="30000" aria-label="${title}" placeholder="${esc(placeholder)}">${esc(state[key])}</textarea><div class="panel-bottom"><label class="upload">＋ 上傳 PDF／文字檔<input class="file-input" id="${key}-file" type="file" accept=".pdf,.txt,.md,application/pdf,text/plain,text/markdown"></label><span class="count" id="${key}-count">${state[key].length.toLocaleString()} 字</span></div><p id="${key}-import-status" class="subtext" role="status">${esc(state.importStatus[key]||'')}</p></section>`}
async function readFile(event,key){
 const input=event.target,file=input.files[0];if(!file||state.documentBusy)return;
 const original=state[key];state.documentBusy=true;state.importStatus[key]='正在讀取文件…';
 const update=message=>{state.importStatus[key]=message;const node=$(`#${key}-import-status`);if(node)node.textContent=message};
 input.disabled=true;['#next','#analyze-documents','#load-trial'].forEach(id=>{const node=$(id);if(node)node.disabled=true});
 try{
  const result=await DocumentImporter.read(file,{onProgress:(page,total)=>update(`正在解析 PDF · ${page} / ${total} 頁`)});
  if(state[key]!==original)throw new Error('欄位已修改，本次匯入未覆蓋你的內容；請重新選擇檔案。');
  const other=state[key==='jd'?'resume':'jd'];
  if(new TextEncoder().encode(result.text+other).length>110000)throw new Error('JD 與履歷合計超過 110 KB，請精簡後再匯入。');
  if(state[key]!==result.text)clearContinuation('已更改面試資料，下一場改為獨立練習。');
  state[key]=result.text;state.analysis=null;state.trialNotice=null;resetPractice();
  update(`已匯入 ${file.name}${result.pages?` · ${result.pages} 頁`:''}，請核對文字與閱讀順序。`);
 }catch(error){update(error.message||'無法讀取此文件，請改用貼上文字。');announce(state.importStatus[key])}
 finally{state.documentBusy=false;input.value='';if(state.step===0)render()}
}
