function liveTranscriptHtml(){
  if(!state.liveHistory.length)return '';
  return `<div class="practice-history session-transcript" role="log" aria-label="實際面試逐字稿">${state.liveHistory.map(turn=>`<article class="practice-turn ${turn.role==='candidate'?'user':'assistant'}"><strong>${turn.role==='candidate'?'你':'AI 面試官'} · ${esc(turn.id)}</strong><p>${esc(turn.content)}</p></article>`).join('')}</div>`;
}
function sessionFeedbackHtml(report){
  return `<div class="practice-report"><h3>這次可以怎麼進步</h3><p>${esc(report.summary||'')}</p>${Array.isArray(report.feedback)?report.feedback.map(item=>{const turn=state.liveHistory.find(turn=>turn.id===item.turnId);return `<article><strong>回答 ${esc(item.turnId||'')}</strong>${turn?`<blockquote>${esc(turn.content)}</blockquote>`:''}<p>${esc(item.observation||'')}</p><p>下次試試：${esc(item.improvement||'')}</p><small>參考原文：${esc((item.evidenceIds||[]).join('、'))}</small></article>`}).join(''):''}${Array.isArray(report.unobserved)&&report.unobserved.length?`<p class="subtext">尚未觀察：${esc(report.unobserved.join('；'))}</p>`:''}<p class="subtext">建議依據本次回答與原始 JD、履歷；不提供錄取率或推測人格。</p></div>`;
}
function reportDocuments(){return state.sessionDocuments?.sessionId===state.lastSessionId?state.sessionDocuments:{jd:state.jd,resume:state.resume}}
