    if(!['pending','ready','empty'].includes(result.state)||!Array.isArray(result.history))throw new Error('逐字稿格式無法辨識，請稍後再查詢。');
    const ids=new Set();const history=result.history.map(turn=>{if(!turn||typeof turn.id!=='string'||!turn.id||ids.has(turn.id)||!['candidate','interviewer'].includes(turn.role)||typeof turn.content!=='string'||!turn.content.trim())throw new Error('逐字稿包含無法辨識的回合，未採用。');ids.add(turn.id);return {id:turn.id,role:turn.role,content:turn.content}});
