  if(state.transcriptState!=='ready'||!state.liveHistory.some(turn=>turn.role==='candidate')){announce('尚未取得候選人的實際回答，無法產生建議。');return}
  if(!reportDocumentsReady()){announce('請補上這場面試使用的同一份 JD 與履歷。');return}
