function continuationExpiryMs(value){const ms=typeof value==='number'?value:typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(value)?Date.parse(value):NaN;return Number.isFinite(ms)&&ms>0&&ms<=8640000000000000?ms:NaN}
